import re,glob
total=0
for p in glob.glob('src/**/*.rs', recursive=True):
    if p.endswith('process.rs'): continue
    s=open(p).read()
    m=re.search(r'#\[cfg\((all\()?test[^\]]*\]\s*\nmod tests', s)
    cut=m.start() if m else len(s)
    head,tail=s[:cut],s[cut:]
    new,n=re.subn(r'(?<![\w:])(?:std::process::)?Command::new\(', 'crate::process::command(', head)
    if n:
        total+=n
        open(p,'w').write(new+tail)
        print(p,n)
print('total',total)
EOF
